import { test, expect } from '@playwright/test';

test.describe('File Upload - Invalid File Type Error', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <html>
        <body>
          <form id="uploadForm">
            <label for="fileInput">Upload File</label>
            <input 
              id="fileInput" 
              type="file" 
              accept=".pdf,.doc,.docx"
              aria-label="File upload input"
            />
            <button type="submit">Upload</button>
          </form>
          <div id="errorMessage" style="display:none; color:red;"></div>
          <div id="successMessage" style="display:none; color:green;"></div>
        </body>
        <script>
          document.getElementById('uploadForm').addEventListener('submit', function(e) {
            e.preventDefault();
            const fileInput = document.getElementById('fileInput');
            const file = fileInput.files[0];
            const errorDiv = document.getElementById('errorMessage');
            const successDiv = document.getElementById('successMessage');

            const allowedExtensions = ['.pdf', '.doc', '.docx'];
            const fileName = file.name;
            const fileExtension = fileName.substring(fileName.lastIndexOf('.')).toLowerCase();

            if (!allowedExtensions.includes(fileExtension)) {
              errorDiv.textContent = 'Error: File type not allowed. Please upload a PDF or Word document.';
              errorDiv.style.display = 'block';
              successDiv.style.display = 'none';
            } else {
              successDiv.textContent = 'File uploaded successfully!';
              successDiv.style.display = 'block';
              errorDiv.style.display = 'none';
            }
          });
        </script>
      </body>
    `);
  });

  test('should display error when uploading unsupported file type', async ({ page }) => {
    const fileInput = page.getByLabel('File upload input');

    // Create a test file with unsupported extension
    const buffer = Buffer.from('test image content');
    await fileInput.setInputFiles({
      name: 'test-image.jpg',
      mimeType: 'image/jpeg',
      buffer: buffer,
    });

    // Submit the form
    await page.getByRole('button', { name: 'Upload' }).click();

    // Verify error message is displayed
    const errorMessage = page.locator('#errorMessage');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Error: File type not allowed');
    await expect(errorMessage).toContainText('PDF or Word document');
  });

  test('should not display error when uploading supported file type', async ({ page }) => {
    const fileInput = page.getByLabel('File upload input');

    // Create a test file with supported extension
    const buffer = Buffer.from('test pdf content');
    await fileInput.setInputFiles({
      name: 'test-document.pdf',
      mimeType: 'application/pdf',
      buffer: buffer,
    });

    // Submit the form
    await page.getByRole('button', { name: 'Upload' }).click();

    // Verify success message is displayed and error is hidden
    const errorMessage = page.locator('#errorMessage');
    const successMessage = page.locator('#successMessage');

    await expect(errorMessage).not.toBeVisible();
    await expect(successMessage).toBeVisible();
    await expect(successMessage).toContainText('File uploaded successfully');
  });

  test('should display error for multiple unsupported file types', async ({ page }) => {
    const fileInput = page.getByLabel('File upload input');
    const unsupportedFiles = [
      { name: 'test.txt', mimeType: 'text/plain' },
      { name: 'test.exe', mimeType: 'application/x-msdownload' },
      { name: 'test.zip', mimeType: 'application/zip' },
    ];

    for (const fileInfo of unsupportedFiles) {
      // Reset form
      await page.reload();

      const buffer = Buffer.from('test content');
      await fileInput.setInputFiles({
        name: fileInfo.name,
        mimeType: fileInfo.mimeType,
        buffer: buffer,
      });

      // Submit the form
      await page.getByRole('button', { name: 'Upload' }).click();

      // Verify error message is displayed
      const errorMessage = page.locator('#errorMessage');
      await expect(errorMessage).toBeVisible();
      await expect(errorMessage).toContainText('Error: File type not allowed');
    }
  });
});
